  readonly int[] multiHits=new int[8];readonly float[] multiUntil=new float[8];readonly int[] target=new int[8];readonly float[] rethink=new float[8],stuck=new float[8],reverseUntil=new float[8];readonly Vector3[] prior=new Vector3[8];readonly NavMeshPath[] paths=new NavMeshPath[8];readonly int[] corner=new int[8];
